(function(a){"use strict";hivepress.authUser=function(b){a.ajax({url:hivepressAuthenticationData.apiURL+b.authenticator,method:"POST",data:b,beforeSend:function(a){a.setRequestHeader("X-WP-Nonce",hivepressCoreData.apiNonce)},complete:function(a){var b=a.responseJSON;(null===b||b.hasOwnProperty("data"))&&window.location.reload(!0)}})},window.onFacebookAuth=function(){FB.getLoginStatus(function(a){"connected"===a.status&&hivepress.authUser({authenticator:"facebook",access_token:a.authResponse.accessToken})})},window.onGoogleAuth=function(a){hivepress.authUser({authenticator:"google",id_token:a.getAuthResponse().id_token}),gapi.auth2.getAuthInstance().disconnect()}})(jQuery);